          "0x1A928|FSTP|extended double ptr [ESP + 0x18]",
          "0x1A92C|FSTP|extended double ptr [ESP]",
          "0x1A92F|MOV|EDX, 0x0",
          "0x1A934|MOV|EAX, dword ptr [ESP + 0x6]",
          "0x1A938|TEST|EAX, 0x7fff0000",
          "0x1A93D|JZ|0x6ff7a949",
